describe('refusals', () => {
  test("npx's cache and other run-once caches are transient; installs aren't", () => {
    for (const p of [
      '/Users/me/.npm/_npx/6913fdfd1ea7a741/node_modules/local-review/dist/server/cli.js',
      'C:\\Users\\me\\AppData\\Local\\npm-cache\\_npx\\abc\\node_modules\\local-review\\dist\\server\\cli.js',
      '/home/me/.cache/pnpm/dlx/abc/node_modules/local-review/dist/server/cli.js',
      '/tmp/bunx-501-local-review@latest/node_modules/local-review/dist/server/cli.js',
      '/tmp/dlx-12345/node_modules/local-review/dist/server/cli.js',
    ])
      assert.ok(transientInstall(p), p);
    for (const p of [
      '/usr/local/lib/node_modules/local-review/dist/server/cli.js',
      '/opt/homebrew/lib/node_modules/local-review/dist/server/cli.js',
      '/home/me/.nvm/versions/node/v22.12.0/lib/node_modules/local-review/dist/server/cli.js',
      '/home/me/.local/share/pnpm/global/5/node_modules/local-review/dist/server/cli.js',
      '/home/me/my_npx_tools/node_modules/local-review/dist/server/cli.js',
    ])
      assert.equal(transientInstall(p), null, p);
  });

  test('says what to do instead', () => {
    const npx = refusal('/Users/me/.npm/_npx/abc/node_modules/local-review/dist/server/cli.js');
    assert.equal(
      npx,
      "Local Review is running from npx's cache, which npm can delete at any time, so a service that runs it would break at some later login. Install it first: `npm i -g local-review`, then run `local-review service install` again.",
    );
    // --from-checkout doesn't let npx through
    assert.equal(refusal('/Users/me/.npm/_npx/abc/node_modules/local-review/dist/server/cli.js', { fromCheckout: true }), npx);
    const checkout = refusal('/home/me/code/local-review/dist/server/cli.js');
    assert.match(checkout!, /^Local Review is running from a source checkout \(\/home\/me\/code\/local-review\), not an installed package/);
    assert.match(checkout!, /`npm i -g local-review`.*add --from-checkout\.$/);
    assert.equal(refusal('/home/me/code/local-review/dist/server/cli.js', { fromCheckout: true }), null);
    assert.equal(refusal('/usr/local/lib/node_modules/local-review/dist/server/cli.js'), null);
    assert.equal(isCheckout('/usr/local/lib/node_modules/local-review/dist/server/cli.js'), false);
  });

  test('Windows and other OSes are refused with what to do instead', () => {
    assert.match(unsupported('win32')!, /doesn't support Windows yet.*Task Scheduler/);
    assert.match(unsupported('freebsd')!, /macOS \(launchd\) and Linux \(systemd\), not freebsd/);
    assert.equal(unsupported('darwin'), null);
    assert.equal(unsupported('linux'), null);
  });
});

describe('the PATH a service gets', () => {
  test("Node's own bin first, then the stable part of this shell's PATH, then the system directories", () => {
    const d = (n: string) => {
      const p = path.join(TMP, 'path', n);
      fs.mkdirSync(p, { recursive: true });
      return p;
    };
    const node = d('node/bin');
    const brew = d('brew/bin');
    const fnm = d('fnm_multishells/123_456/bin');
    const npx = d('.npm/_npx/abc/node_modules/.bin');
    const nm = d('project/node_modules/.bin');
    const gyp = d('npm/node-gyp-bin');
    const p = servicePath(node, [fnm, 'relative/bin', brew, '/no/such/dir', npx, nm, gyp, node, `${brew}/`, ''].join(':')).split(':');
    assert.deepEqual(p.slice(0, 2), [node, brew]);
    for (const gone of [fnm, npx, nm, gyp, 'relative/bin', '/no/such/dir']) assert.ok(!p.includes(gone), gone);
    assert.ok(p.includes('/usr/bin') && p.includes('/bin'), 'the system directories, where they exist');
    assert.equal(new Set(p).size, p.length, 'no duplicates');
  });

  test('where the definition goes', () => {
    assert.equal(serviceDir({ platform: 'darwin', userHome: '/Users/me', env: {} }), '/Users/me/Library/LaunchAgents');
    assert.equal(serviceDir({ platform: 'linux', userHome: '/home/me', env: {} }), '/home/me/.config/systemd/user');
    assert.equal(serviceDir({ platform: 'linux', userHome: '/home/me', env: { XDG_CONFIG_HOME: '/xdg' } }), '/xdg/systemd/user');
    assert.equal(serviceDir({ platform: 'linux', userHome: '/home/me', env: { XDG_CONFIG_HOME: 'relative' } }), '/home/me/.config/systemd/user');
    assert.equal(portOf(['node', 'cli.js', 'serve', '--port', '6001']), 6001);
    assert.equal(portOf(['node', 'cli.js', 'serve']), null);
  });
});

// ---------------------------------------------------------------------------------------------------------------
// The lifecycle, with launchctl / systemctl mocked
// ---------------------------------------------------------------------------------------------------------------

let n = 0;
/** A world: a user home, an installed (or checked-out, or npx-cached) package, a PATH with git on it. */
function world(platform: 'darwin' | 'linux', { where = 'global', git = true }: { where?: 'global' | 'npx' | 'checkout'; git?: boolean } = {}) {
  const base = path.join(TMP, `w${++n}`);
  const userHome = path.join(base, 'home');
  const root =
    where === 'global'
      ? path.join(base, 'prefix', 'lib', 'node_modules', 'local-review')
      : where === 'npx'
        ? path.join(userHome, '.npm', '_npx', 'abc', 'node_modules', 'local-review')
        : path.join(base, 'code', 'local-review');
  fs.mkdirSync(path.join(root, 'dist', 'server'), { recursive: true });
  fs.writeFileSync(path.join(root, 'dist', 'server', 'cli.js'), '');
  fs.writeFileSync(path.join(root, 'package.json'), '{"name": "local-review", "version": "9.9.9"}');
  const bin = path.join(base, 'bin');
  fs.mkdirSync(bin, { recursive: true });
  fs.mkdirSync(userHome, { recursive: true });
  if (git) fs.writeFileSync(path.join(bin, 'git'), '#!/bin/sh\n', { mode: 0o755 });
  const node = path.join(base, 'node', 'bin', 'node');
  fs.mkdirSync(path.dirname(node), { recursive: true });
  fs.writeFileSync(node, '', { mode: 0o755 });

  // the service manager's state, as the mocked commands see it
  const calls: string[] = [];
  // refuse: the verbs the manager refuses (exit 1), e.g. a systemd that won't start the unit, a bootstrap launchd won't do
  const state = { loaded: false, running: false, enabled: false, pid: 100, refuse: [] as string[] };
  const run: Runner = async (cmd, args): Promise<RunResult> => {
    calls.push(`${cmd} ${args.join(' ')}`);
    const ok = (stdout = '') => ({ code: 0, stdout, stderr: '' });
    if (cmd === 'systemctl') {
      const [, verb] = args;
      if (state.refuse.includes(verb)) return { code: 1, stdout: '', stderr: `Failed to ${verb} unit: refused` };
      if (verb === 'show') {
        const file = fs.existsSync(path.join(userHome, '.config', 'systemd', 'user', 'local-review-server.service'));
        return ok(
          `LoadState=${file || state.loaded ? 'loaded' : 'not-found'}\nActiveState=${state.running ? 'active' : 'inactive'}\nSubState=${state.running ? 'running' : 'dead'}\nMainPID=${state.running ? state.pid : 0}\nExecMainStatus=0\nExecMainPID=0\nUnitFileState=${state.enabled ? 'enabled' : file ? 'disabled' : ''}\n`,
        );
      }
      if (verb === 'enable') state.enabled = true;
      if (verb === 'disable') state.enabled = false;
      if (verb === 'start' || verb === 'restart') Object.assign(state, { loaded: true, running: true, pid: state.pid + 1 });
      if (verb === 'stop') state.running = false;
      if (verb === 'daemon-reload') state.loaded = fs.existsSync(path.join(userHome, '.config', 'systemd', 'user', 'local-review-server.service'));
      return ok();
    }
    if (cmd === 'launchctl') {
      const [verb] = args;
      if (state.refuse.includes(verb)) return { code: 1, stdout: '', stderr: `${verb}: refused` };
      if (verb === 'print') return state.loaded ? ok(`x = {\n\tstate = ${state.running ? 'running' : 'not running'}\n${state.running ? `\tpid = ${state.pid}\n` : ''}}\n`) : { code: 113, stdout: '', stderr: 'Could not find service' };
      if (verb === 'bootstrap') Object.assign(state, { loaded: true, running: true, pid: state.pid + 1 });
      if (verb === 'bootout') Object.assign(state, { loaded: false, running: false });
      if (verb === 'kickstart') Object.assign(state, { running: true, pid: state.pid + 1 });
      return ok();
    }
    return { code: 127, stdout: '', stderr: `${cmd}: command not found` };
  };
  const out: string[] = [];
  const err: string[] = [];
  const ctx: ServiceContext = {
    platform,
    userHome,
    env: { PATH: `${bin}:/usr/bin:/bin` },
    uid: 501,
    run,
    sleep: async () => {},
    root,
    execPath: node,
    nodeVersion: 'v22.12.0',
    out: (s) => out.push(s),
    err: (s) => err.push(s),
    waitMs: 0,
    isListening: async () => false,
    health: async () => (state.running ? { version: '9.9.9' } : null),
    // /api/busy: nothing answers, unless a test says otherwise
    fetch: async () => {
      throw new Error('connection refused');
    },
  };
  const file = platform === 'darwin' ? path.join(userHome, 'Library', 'LaunchAgents', 'local-review.server.plist') : path.join(userHome, '.config', 'systemd', 'user', 'local-review-server.service');
  const take = () => {
    const o = out.join('');
    const e = err.join('');
    out.length = err.length = calls.length = 0;
    return { out: o, err: e };
  };
  return { ctx, calls, state, file, root, userHome, node, bin, take, cli: path.join(root, 'dist', 'server', 'cli.js') };
}

describe('service install, on Linux (systemd)', () => {
  test('writes the unit, enables and starts it, and says where it is and how long it lives', async () => {
    const w = world('linux');
    assert.equal(await install(w.ctx, {}), 0);
    const { out } = w.take();
    const text = fs.readFileSync(w.file, 'utf8');
    assert.match(text, new RegExp(`^ExecStart=${w.node} ${w.cli} serve --quiet --port 5622$`, 'm'));
    assert.match(text, new RegExp(`^Environment="PATH=${path.dirname(w.node)}:${w.bin}:/usr/bin:/bin`, 'm'));
    assert.match(text, new RegExp(`^Environment="HOME=${w.userHome}"$`, 'm'), 'HOME: the one install resolved the data home from');
    assert.doesNotMatch(text, /LOCAL_REVIEW_HOME|LOCAL_REVIEW_USER|PORT=/, 'nothing carried over that was never set');
    assert.match(text, new RegExp(`^StandardOutput=append:${w.userHome}/.local-review/logs/service.log$`, 'm'));
    assert.match(text, new RegExp(`^StandardError=append:${w.userHome}/.local-review/logs/service.log$`, 'm'), 'one log file for both');
    assert.ok(fs.statSync(path.join(w.userHome, '.local-review', 'logs')).isDirectory(), 'the logs directory exists for systemd to append to');
    assert.equal(
      out,
      [
        "Installed Local Review as a systemd user unit: ~/.config/systemd/user/local-review-server.service",
        "It's running: http://localhost:5622",
        "It starts with your user session and is restarted if it exits. To keep it running while you're logged out, and start it at boot, enable lingering once: `loginctl enable-linger $USER`.",
        'Data: ~/.local-review. Log: ~/.local-review/logs/service.log (`local-review service logs`).',
        '',
      ].join('\n'),
    );
  });

  test('again: idempotent, then a new port rewrites and restarts it, and a bare reinstall keeps that port', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.take();
    // unchanged: no daemon-reload, but the running service is restarted, not left serving the old process: systemd's
    // start leaves an active unit alone (cli-contract SPEC §1)
    assert.equal(await install(w.ctx, {}), 0);
    const calls = [...w.calls];
    let r = w.take();
    assert.match(r.out, /^Installed Local Review as a systemd user unit: .* \(unchanged\)$/m);
    assert.ok(!calls.includes('systemctl --user daemon-reload'), calls.join('\n'));
    assert.ok(calls.includes('systemctl --user restart local-review-server.service'), calls.join('\n'));
    // stopped, and unchanged: a start, not a restart (systemd allows five starts in ten seconds)
    w.state.running = false;
    assert.equal(await install(w.ctx, {}), 0);
    assert.ok(w.calls.includes('systemctl --user start local-review-server.service') && !w.calls.includes('systemctl --user restart local-review-server.service'), w.calls.join('\n'));
    w.take();
    // a new port
    await install(w.ctx, { port: 6001 });
    assert.match(fs.readFileSync(w.file, 'utf8'), /--port 6001$/m);
    assert.ok(w.calls.includes('systemctl --user daemon-reload') && w.calls.includes('systemctl --user restart local-review-server.service'), w.calls.join('\n'));
    r = w.take();
    assert.match(r.out, /It's running: http:\/\/localhost:6001/);
    // no --port: kept
    await install(w.ctx, {});
    r = w.take();
    assert.match(fs.readFileSync(w.file, 'utf8'), /--port 6001$/m);
    assert.match(r.out, /\(unchanged\)\nPort 6001, as it was installed \(--port changes it\)\.\n/);
  });

  test('LOCAL_REVIEW_HOME and LOCAL_REVIEW_USER: carried over (made absolute), and kept by a reinstall without them', async () => {
    const w = world('linux');
    w.ctx.env = { ...w.ctx.env, LOCAL_REVIEW_HOME: '~/review-data', LOCAL_REVIEW_USER: 'Ed' };
    await install(w.ctx, {});
    const data = path.join(w.userHome, 'review-data');
    let text = fs.readFileSync(w.file, 'utf8');
    assert.match(text, new RegExp(`^Environment="LOCAL_REVIEW_HOME=${data}"$`, 'm'));
    assert.match(text, /^Environment="LOCAL_REVIEW_USER=Ed"$/m);
    assert.match(text, new RegExp(`^WorkingDirectory=${data}$`, 'm'));
    assert.ok(fs.existsSync(path.join(data, 'logs')));
    assert.match(w.take().out, /Data: ~\/review-data\. Log: ~\/review-data\/logs\/service\.log/);
    w.ctx.env = { PATH: w.ctx.env.PATH };
    await install(w.ctx, {});
    text = fs.readFileSync(w.file, 'utf8');
    assert.match(text, new RegExp(`^Environment="LOCAL_REVIEW_HOME=${data}"$`, 'm'));
    const { out } = w.take();
    assert.match(out, /\(unchanged\)/);
    assert.match(out, new RegExp(`LOCAL_REVIEW_HOME=${data}, as it was installed \\(uninstall first to drop it\\)\\.`));
  });

  test('$PORT is not the service port', async () => {
    const w = world('linux');
    w.ctx.env = { ...w.ctx.env, PORT: '4000' };
    await install(w.ctx, {});
    assert.match(fs.readFileSync(w.file, 'utf8'), /--port 5622$/m);
    assert.doesNotMatch(fs.readFileSync(w.file, 'utf8'), /PORT=4000/);
  });

  test('--dry-run prints the unit and writes nothing, starts nothing', async () => {
    const w = world('linux');
    assert.equal(await install(w.ctx, { dryRun: true, port: 7000 }), 0);
    const { out } = w.take();
    assert.match(out, /^Would write the systemd user unit ~\/\.config\/systemd\/user\/local-review-server\.service \(--dry-run: nothing written, nothing started\):\n\n# Generated by Local Review/);
    assert.match(out, /--port 7000$/m);
    assert.ok(!fs.existsSync(w.file));
    assert.ok(!fs.existsSync(path.join(w.userHome, '.local-review')), 'not even the logs directory');
    assert.deepEqual(w.calls, []);
  });

  test("refuses npx's cache and a source checkout, writing nothing; --from-checkout runs the checkout", async () => {
    const npx = world('linux', { where: 'npx' });
    await assert.rejects(install(npx.ctx, {}), /running from npx's cache.*`npm i -g local-review`/);
    await assert.rejects(install(npx.ctx, { fromCheckout: true }), /npx's cache/);
    assert.ok(!fs.existsSync(npx.file));
    assert.deepEqual(npx.calls, []);

    const co = world('linux', { where: 'checkout' });
    await assert.rejects(install(co.ctx, {}), /running from a source checkout .* add --from-checkout\./);
    assert.ok(!fs.existsSync(co.file));
    assert.equal(await install(co.ctx, { fromCheckout: true }), 0);
    assert.match(fs.readFileSync(co.file, 'utf8'), new RegExp(`^ExecStart=${co.node} ${co.cli} serve`, 'm'));
    // ...but it has to have been built
    fs.rmSync(path.join(co.root, 'dist'), { recursive: true });
    await assert.rejects(install(co.ctx, { fromCheckout: true }), /dist\/server\/cli\.js doesn't exist: build Local Review first \(npm run build\)/);
  });

  test('refuses without git on the PATH, and when the port is taken by something else', async () => {
    const w = world('linux', { git: false });
    w.ctx.env = { PATH: w.bin }; // no /usr/bin either
    const nogit = await install(w.ctx, {}).catch((e) => e);
    if (!fs.existsSync('/usr/bin/git') && !fs.existsSync('/bin/git') && !fs.existsSync('/usr/local/bin/git') && !fs.existsSync('/opt/homebrew/bin/git')) {
      assert.match(nogit.message, /can't find git on your PATH .* Local Review runs git to read your repos/);
      assert.ok(!fs.existsSync(w.file));
    } // (else this machine's system directories have git, which the service's PATH rightly includes)

    const busy = world('linux');
    busy.ctx.isListening = async () => true;
    await assert.rejects(install(busy.ctx, {}), /port 5622 is already in use \(is `local-review` running in a terminal\?\)\. Stop that first, or pick another port with --port <n>\./);
    assert.ok(!fs.existsSync(busy.file));
  });

  test("a service that doesn't come up: exit 1, with the last lines of its log", async () => {
    const w = world('linux');
    w.ctx.health = async () => null;
    const logs = path.join(w.userHome, '.local-review', 'logs');
    fs.mkdirSync(logs, { recursive: true });
    fs.writeFileSync(path.join(logs, 'service.log'), 'Local Review on …\nlocal-review: port 5622 is already in use; pick another with --port <n>\n');
    assert.equal(await install(w.ctx, {}), 1);
    const { err } = w.take();
    assert.match(err, /^local-review: the service was started, but nothing answered on http:\/\/localhost:5622 in time\.\n\nThe last lines of its log:\n==> .*service\.log <==\nLocal Review on …\nlocal-review: port 5622 is already in use/);
  });
});

describe('service install, on macOS (launchd)', () => {
  test('writes the plist and bootstraps it; a changed plist is booted out and in again', async () => {
    const w = world('darwin');
    assert.equal(await install(w.ctx, {}), 0);
    assert.deepEqual(w.calls, [
      'launchctl print gui/501/local-review.server',
      'launchctl enable gui/501/local-review.server',
      'launchctl print gui/501/local-review.server',
      `launchctl bootstrap gui/501 ${w.file}`,
    ]);
    const { out } = w.take();
    assert.match(out, /^Installed Local Review as a LaunchAgent: ~\/Library\/LaunchAgents\/local-review\.server\.plist\nIt's running: http:\/\/localhost:5622\nIt starts at login and is restarted if it exits\.\n/);
    const def = parsePlist(fs.readFileSync(w.file, 'utf8'))!;
    assert.deepEqual(def.program, [w.node, w.cli, 'serve', '--quiet', '--port', '5622']);
    assert.equal(def.env.PATH.split(':')[0], path.dirname(w.node));

    // the same again, over the running service: it's replaced, not left serving the old process (cli-contract SPEC §1)
    await install(w.ctx, {});
    assert.deepEqual(w.calls, ['launchctl print gui/501/local-review.server', 'launchctl print gui/501/local-review.server', 'launchctl kickstart -k gui/501/local-review.server']);
    w.take();
    // a new port: launchd only reads a plist at bootstrap
    await install(w.ctx, { port: 6001 });
    assert.ok(w.calls.join('\n').includes(`launchctl bootout gui/501/local-review.server\nlaunchctl print gui/501/local-review.server\nlaunchctl enable gui/501/local-review.server\nlaunchctl bootstrap gui/501 ${w.file}`), w.calls.join('\n'));
  });
});

describe("a first install the service manager refuses leaves no unit behind (cli-contract d5ddc0e)", () => {
  test('systemd refuses the start: the unit is disabled, removed and reloaded away, and status says not installed', async () => {
    const w = world('linux');
    w.state.refuse = ['start'];
    await assert.rejects(install(w.ctx, {}), /systemctl --user start local-review-server\.service failed \(exit 1\)/);
    assert.equal(fs.existsSync(w.file), false, 'status would otherwise say it is installed');
    assert.deepEqual(w.calls.slice(-2), ['systemctl --user disable --quiet local-review-server.service', 'systemctl --user daemon-reload']);
    w.state.refuse = [];
    w.take();
    assert.equal(await status(w.ctx), 4);
  });

  test("systemd refuses the reload or the enable, after the unit was written: it's taken back too", async () => {
    for (const verb of ['daemon-reload', 'enable']) {
      const w = world('linux');
      w.state.refuse = [verb];
      await assert.rejects(install(w.ctx, {}), new RegExp(`systemctl --user ${verb}.* failed \\(exit 1\\)`), verb);
      assert.equal(fs.existsSync(w.file), false, verb);
      assert.ok(fs.statSync(path.join(w.userHome, '.local-review', 'logs')).isDirectory(), 'the data home is left as it is');
    }
  });

  test('launchd refuses the bootstrap: the plist is removed', async () => {
    const w = world('darwin');
    w.state.refuse = ['bootstrap'];
    await assert.rejects(install(w.ctx, {}), /launchctl bootstrap .* failed \(exit 1\)/);
    assert.equal(fs.existsSync(w.file), false);
  });

  test('control: a refused reinstall keeps the unit it had, on both', async () => {
    for (const [platform, verb] of [
      ['linux', 'restart'],
      ['darwin', 'bootstrap'],
    ] as const) {
      const w = world(platform);
      assert.equal(await install(w.ctx, {}), 0);
      w.state.refuse = [verb];
      // a new port: the definition changes, so the reinstall restarts (launchd: boots out and bootstraps) it
      await assert.rejects(install(w.ctx, { port: 6001 }), /failed \(exit 1\)/, platform);
      assert.ok(fs.existsSync(w.file), `${platform}: a reinstall keeps its unit`);
      assert.match(fs.readFileSync(w.file, 'utf8'), /6001/, `${platform}: the unit that's there, as written`);
      assert.ok(!w.calls.some((c) => / disable /.test(c)), `${platform}: nothing disabled`);
    }
  });
});

describe('service status, start, stop, restart, logs and uninstall', () => {
  test('status: not installed (exit 4)', async () => {
    const w = world('linux');
    assert.equal(await status(w.ctx), 4);
    assert.equal(w.take().out, 'Service:   not installed (`local-review service install`)\nLoaded:    no\nRunning:   no\n');
    assert.equal(await status(w.ctx, { json: true }), 4);
    assert.equal(JSON.parse(w.take().out).installed, false);
  });

  test('status: no service manager to ask (no systemd), and no file: not installed (exit 4); with a file: an error', async () => {
    const w = world('linux');
    w.ctx.run = async () => ({ code: 127, stdout: '', stderr: 'systemctl: command not found' });
    assert.equal(await status(w.ctx), 4);
    assert.match(w.take().out, /^Service:   not installed/);
    fs.mkdirSync(path.dirname(w.file), { recursive: true });
    fs.writeFileSync(w.file, '[Service]\n');
    await assert.rejects(status(w.ctx), /systemctl is not available/);
  });

  test('status: installed and running (exit 0), as text and JSON; stopped (exit 3)', async () => {
    const w = world('linux');
    await install(w.ctx, { port: 6001 });
    w.take();
    assert.equal(await status(w.ctx), 0);
    const t = (p: string) => p.replace(w.userHome, '~');
    assert.equal(
      w.take().out,
      [
        'Service:   ~/.config/systemd/user/local-review-server.service',
        'Loaded:    yes (active (running)), starts at login',
        `Running:   yes, pid ${w.state.pid}`,
        'UI:        http://localhost:6001',
        'Version:   9.9.9',
        `Node:      ${t(w.node)}`,
        `Runs:      ${t(w.cli)}`,
        'Data:      ~/.local-review',
        'Log:       ~/.local-review/logs/service.log',
        '',
      ].join('\n'),
    );
    const r = await statusReport(w.ctx);
    assert.equal(r.port, 6001);
    assert.equal(r.answering, true);
    assert.equal(r.version, '9.9.9');
    assert.equal(r.installedVersion, '9.9.9');
    assert.equal(r.manager, 'systemd');
    assert.deepEqual(r.warnings, []);
    assert.equal(await status(w.ctx, { json: true }), 0);
    assert.equal(JSON.parse(w.take().out).url, 'http://localhost:6001');

    // installed but not running: 3, with --json too
    w.state.running = false;
    assert.equal(await status(w.ctx), 3);
    assert.match(w.take().out, /^Running:   no$/m);
    assert.equal(await status(w.ctx, { json: true }), 3);
    const j = JSON.parse(w.take().out);
    assert.equal(j.running, false);
    assert.equal(j.version, null);
    assert.equal(j.installedVersion, '9.9.9');
    // running, but not answering: 3 as well
    w.state.running = true;
    w.ctx.health = async () => null;
    assert.equal(await status(w.ctx), 3);
    assert.match(w.take().out, /^UI:        nothing answering on http:\/\/localhost:6001$/m);
  });

  test("status warns when what it runs is gone, or isn't this local-review, or an older version still runs", async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.ctx.health = async () => ({ version: '9.8.0' });
    assert.match((await statusReport(w.ctx)).warnings.join('\n'), /It's running 9\.8\.0, but 9\.9\.9 is installed: `local-review service restart` runs 9\.9\.9\./);
    fs.rmSync(w.node);
    assert.match((await statusReport(w.ctx)).warnings.join('\n'), /The Node it runs, .*node, isn't there any more: run `local-review service install` again\./);
    const other = world('linux');
    other.ctx.userHome = w.userHome; // the same service, seen from another installed local-review
    assert.match((await statusReport(other.ctx)).warnings.join('\n'), /It runs .*, not this local-review \(.*\)\. `local-review service install` points it at this one\./);
  });

  test('start, stop, restart and logs: exit 4 when not installed', async () => {
    const w = world('linux');
    for (const verb of [start, stop, restart, logs]) {
      assert.equal(await verb(w.ctx), 4, verb.name);
      assert.equal(w.take().err, "local-review: Local Review isn't installed as a service; install it with `local-review service install`\n");
    }
    assert.ok(!fs.existsSync(w.file));
  });

  test('stop (systemd): stopped, not disabled; start brings it back', async () => {
    const w = world('linux');
    await install(w.ctx, { port: 6003 });
    w.take();
    assert.equal(await stop(w.ctx), 0);
    assert.deepEqual(w.calls.filter((c) => !c.includes(' show ')), ['systemctl --user stop local-review-server.service']);
    assert.equal(
      w.take().out,
      'Stopped Local Review. It starts again with your next login session (or at boot, with lingering on), or with `local-review service start`. To keep it off, `local-review service uninstall`.\n',
    );
    assert.equal(w.state.running, false);
    assert.equal(w.state.enabled, true, 'still enabled: the next login starts it');
    assert.ok(fs.existsSync(w.file), 'still installed');
    assert.equal(await status(w.ctx), 3);
    w.take();
    // again: nothing was running
    assert.equal(await stop(w.ctx), 0);
    assert.match(w.take().out, /^Local Review's service wasn't running\. /);

    assert.equal(await start(w.ctx), 0);
    assert.deepEqual(w.calls.filter((c) => !c.includes(' show ')), [
      'systemctl --user enable --quiet local-review-server.service',
      'systemctl --user reset-failed local-review-server.service', // a unit that hit the start limit stays failed until this
      'systemctl --user start local-review-server.service',
    ]);
    assert.equal(w.take().out, 'Started Local Review: http://localhost:6003\n');
    assert.equal(await start(w.ctx), 0);
    assert.equal(w.take().out, 'Local Review is already running: http://localhost:6003\n');
  });

  test('stop (launchd): booted out, never disabled; start bootstraps it again', async () => {
    const w = world('darwin');
    await install(w.ctx, {});
    w.take();
    assert.equal(await stop(w.ctx), 0);
    // the bootout, then `print` until the job has gone (it already has here)
    assert.deepEqual(w.calls, ['launchctl print gui/501/local-review.server', 'launchctl bootout gui/501/local-review.server', 'launchctl print gui/501/local-review.server']);
    assert.match(w.take().out, /^Stopped Local Review\. It starts again at your next login, or with `local-review service start`\./);
    assert.ok(fs.existsSync(w.file), 'the plist stays: RunAtLoad starts it at the next login');
    assert.equal(await start(w.ctx), 0);
    assert.ok(w.calls.includes(`launchctl bootstrap gui/501 ${w.file}`), w.calls.join('\n'));
    assert.ok(!w.calls.some((c) => c.includes(' disable ')));
  });

  test("start: refuses a port taken by something else; a service that doesn't answer is exit 1 with its log", async () => {
    const w = world('linux');
    await install(w.ctx, {});
    await stop(w.ctx);
    w.take();
    w.ctx.isListening = async () => true;
    await assert.rejects(start(w.ctx), /port 5622 is already in use \(is `local-review` running in a terminal\?\)/);
    w.ctx.isListening = async () => false;
    w.ctx.health = async () => null;
    fs.writeFileSync(path.join(w.userHome, '.local-review', 'logs', 'service.log'), 'Error: boom\n');
    assert.equal(await start(w.ctx), 1);
    assert.match(w.take().err, /^local-review: started the service, but nothing answered on http:\/\/localhost:5622 in time\.\n\nThe last lines of its log:\n==> .*service\.log <==\nError: boom\n$/);
  });

  test('restart: restarts an installed service, leaving a current unit alone', async () => {
    const w = world('linux');
    await install(w.ctx, { port: 6002 });
    w.take();
    assert.equal(await restart(w.ctx), 0);
    assert.deepEqual(w.calls, ['systemctl --user enable --quiet local-review-server.service', 'systemctl --user reset-failed local-review-server.service', 'systemctl --user restart local-review-server.service']);
    assert.equal(w.take().out, 'Restarted Local Review: http://localhost:6002\n');
  });

  test('restart: a unit an older version wrote (two log files) is rewritten in this format, keeping what it runs', async () => {
    const w = world('linux');
    w.ctx.env = { ...w.ctx.env, LOCAL_REVIEW_HOME: '~/rd' };
    await install(w.ctx, { port: 6004 });
    const data = path.join(w.userHome, 'rd');
    const current = fs.readFileSync(w.file, 'utf8');
    const old = current
      .replace(/^StandardOutput=append:.*$/m, `StandardOutput=append:${data}/logs/server.out.log`)
      .replace(/^StandardError=append:.*$/m, `StandardError=append:${data}/logs/server.err.log`);
    fs.writeFileSync(w.file, old);
    fs.writeFileSync(path.join(data, 'logs', 'server.out.log'), 'Local Review on http://localhost:6004\n');
    fs.writeFileSync(path.join(data, 'logs', 'server.err.log'), 'a warning\n');
    w.take();
    w.ctx.env = { PATH: w.ctx.env.PATH }; // from a shell without LOCAL_REVIEW_HOME: still kept

    // status and logs say what's going on first
    assert.match((await statusReport(w.ctx)).warnings.join('\n'), /as an older Local Review set it up\. `local-review service restart` moves it to one file, logs\/service\.log\./);
    assert.equal(await logs(w.ctx), 0);
    let r = w.take();
    assert.match(r.err, /two log files/);
    assert.equal(r.out, `==> ${data}/logs/server.out.log <==\nLocal Review on http://localhost:6004\n==> ${data}/logs/server.err.log <==\na warning\n`);

    assert.equal(await restart(w.ctx), 0);
    assert.equal(fs.readFileSync(w.file, 'utf8'), current, 'exactly what install writes now');
    assert.ok(w.calls.includes('systemctl --user daemon-reload'), w.calls.join('\n'));
    r = w.take();
    assert.equal(r.out, `Updated its systemd user unit (~/.config/systemd/user/local-review-server.service). Log: ~/rd/logs/service.log.\nRestarted Local Review: http://localhost:6004\n`);
    assert.ok(fs.existsSync(path.join(data, 'logs', 'server.out.log')), 'the old logs stay');
    assert.deepEqual((await statusReport(w.ctx)).warnings, []);
  });

  test('restart: a unit whose Node has gone is pointed at this local-review and its Node', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    const gone = path.join(path.dirname(w.node), 'old-node');
    fs.writeFileSync(w.file, fs.readFileSync(w.file, 'utf8').replace(`ExecStart=${w.node} `, `ExecStart=${gone} `));
    w.take();
    assert.equal(await restart(w.ctx), 0);
    assert.match(fs.readFileSync(w.file, 'utf8'), new RegExp(`^ExecStart=${w.node} ${w.cli} serve`, 'm'));
    assert.match(w.take().out, /^Updated its systemd user unit \(.*\): it runs .*cli\.js now, with Node v22\.12\.0\. Log: /);
  });

  test('logs: the last 50 lines, -n, a log not written yet, and -f following what comes next', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    const log = path.join(w.userHome, '.local-review', 'logs', 'service.log');
    w.take();
    assert.equal(await logs(w.ctx), 0);
    assert.match(w.take().err, /^No log yet at ~\/\.local-review\/logs\/service\.log: the service writes it when it starts\.\n$/);

    fs.writeFileSync(log, Array.from({ length: 120 }, (_, i) => `line ${i + 1}`).join('\n') + '\n');
    assert.equal(await logs(w.ctx), 0);
    let { out } = w.take();
    assert.equal(out.split('\n').length, 51);
    assert.ok(out.startsWith('line 71\n') && out.endsWith('line 120\n'));
    await logs(w.ctx, { lines: 3 });
    assert.equal(w.take().out, 'line 118\nline 119\nline 120\n');
    await logs(w.ctx, { lines: 0 });
    assert.equal(w.take().out, '');

    const ac = new AbortController();
    w.ctx.signal = ac.signal;
    w.ctx.pollMs = 10;
    const following = logs(w.ctx, { lines: 1, follow: true });
    await new Promise((r) => setTimeout(r, 30));
    fs.appendFileSync(log, 'line 121\n');
    await new Promise((r) => setTimeout(r, 50));
    fs.appendFileSync(log, 'line 122\n');
    ac.abort();
    assert.equal(await following, 0);
    ({ out } = w.take());
    assert.equal(out, 'line 120\nline 121\nline 122\n');
  });

  test('tailLines reads only the end, across chunk boundaries', () => {
    const f = path.join(TMP, 'big.log');
    const lines = Array.from({ length: 20000 }, (_, i) => `${i} ${'x'.repeat(i % 50)}`);
    fs.writeFileSync(f, lines.join('\n') + '\n');
    assert.equal(tailLines(f, 3), lines.slice(-3).join('\n') + '\n');
    assert.equal(tailLines(f, 5000), lines.slice(-5000).join('\n') + '\n');
    fs.writeFileSync(f, 'no newline at the end');
    assert.equal(tailLines(f, 2), 'no newline at the end\n');
    assert.equal(tailLines(path.join(TMP, 'none.log'), 2), null);
  });

  test('uninstall: stops it and removes its file, and nothing else; a second time has nothing to do', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    const data = path.join(w.userHome, '.local-review');
    fs.writeFileSync(path.join(data, 'logs', 'service.log'), 'Local Review on http://localhost:5622\n');
    w.take();
    assert.equal(await uninstall(w.ctx), 0);
    assert.equal(w.take().out, "Removed Local Review's service (~/.config/systemd/user/local-review-server.service). Your data in ~/.local-review is untouched.\n");
    assert.ok(!fs.existsSync(w.file));
    assert.equal(fs.readFileSync(path.join(data, 'logs', 'service.log'), 'utf8'), 'Local Review on http://localhost:5622\n', 'the logs stay');
    assert.equal(await uninstall(w.ctx), 0);
    assert.equal(w.take().out, "Local Review wasn't installed as a service; nothing to do.\n");
  });

  test('uninstall works from npx (it only removes)', async () => {
    const w = world('darwin');
    await install(w.ctx, {});
    const npx = world('darwin', { where: 'npx' });
    npx.ctx.userHome = w.userHome;
    npx.ctx.run = w.ctx.run;
    assert.equal(await uninstall(npx.ctx), 0);
    assert.ok(!fs.existsSync(w.file));
  });

  test('removeServiceFile removes only the service file, only in its directory', () => {
    const dir = path.join(TMP, 'rm');
    fs.mkdirSync(dir);
    for (const f of ['local-review-server.service', 'project.yaml', 'local-review.server.plist']) fs.writeFileSync(path.join(dir, f), 'x');
    assert.throws(() => removeServiceFile(path.join(dir, 'project.yaml'), dir), /refusing to remove/);
    assert.throws(() => removeServiceFile(path.join(dir, 'local-review-server.service'), path.join(dir, 'elsewhere')), /refusing to remove/);
    assert.throws(() => removeServiceFile(path.join(dir, '..', path.basename(dir), 'sub', 'local-review-server.service'), dir), /refusing to remove/);
    removeServiceFile(path.join(dir, 'local-review-server.service'), dir);
    removeServiceFile(path.join(dir, 'local-review-server.service'), dir); // already gone: fine
    assert.deepEqual(fs.readdirSync(dir).sort(), ['local-review.server.plist', 'project.yaml']);
    assert.ok(SERVICE_FILE.test('local-review.server.plist') && !SERVICE_FILE.test('local-review.server.plist.bak'));
    assert.equal(LABEL, 'local-review.server');
  });
});

describe('busy: service stop and restart refuse with 75 unless --force (cli-contract SPEC §4)', () => {
  const answer = (body: unknown) => async () => new Response(JSON.stringify(body), { headers: { 'content-type': 'application/json' } });
  const BUSY = { busy: true, version: '9.9.9', counts: { save: 1, snapshot: 0, sync: 1 } };

  for (const platform of ['linux', 'darwin'] as const)
    test(`${platform}: busy, stop and restart refuse and change nothing; idle, they go ahead`, async () => {
      const w = world(platform);
      await install(w.ctx, {});
      w.take();
      const asked: string[] = [];
      w.ctx.fetch = async (url) => {
        asked.push(String(url));
        return answer(BUSY)();
      };
      assert.equal(await stop(w.ctx), 75);
      assert.deepEqual(asked, ['http://127.0.0.1:5622/api/busy'], 'it asks the port the service file names');
      let r = w.take();
      assert.equal(r.out, '');
      assert.equal(
        r.err,
        'local-review: Local Review is busy: 1 save and 1 GitHub sync are running. Try again once it has finished (`local-review busy` says when), or stop it anyway with --force.\n',
      );
      assert.equal(w.state.running, true, 'still running');
      assert.equal(await restart(w.ctx), 75);
      r = w.take();
      assert.match(r.err, /or restart it anyway with --force\.\n$/);
      assert.ok(!r.out.includes('Restarted'));

      w.ctx.fetch = answer({ busy: false, version: '9.9.9', counts: { save: 0, snapshot: 0, sync: 0 } });
      assert.equal(await restart(w.ctx), 0);
      assert.equal(w.take().err, '');
      assert.equal(await stop(w.ctx), 0);
      assert.equal(w.state.running, false);
    });

  test("status: what /api/busy says, and the schema's runningVersion and unit", async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.take();
    w.ctx.fetch = answer(BUSY);
    assert.equal(await status(w.ctx), 0, 'busy is still running and answering');
    assert.match(w.take().out, /^Busy:      yes \(1 save and 1 GitHub sync are running\)$/m);
    assert.equal(await status(w.ctx, { json: true }), 0);
    const j = JSON.parse(w.take().out);
    assert.deepEqual(j.busy, { busy: true, counts: BUSY.counts });
    assert.equal(j.runningVersion, '9.9.9');
    assert.equal(j.unit, w.file);
    w.ctx.fetch = answer({ busy: false, counts: {} });
    await status(w.ctx);
    assert.match(w.take().out, /^Busy:      no$/m);
    // nothing answering /api/busy (an older version): no busy line, no busy field
    w.ctx.fetch = async () => new Response('', { status: 404 });
    await status(w.ctx, { json: true });
    assert.equal(JSON.parse(w.take().out).busy, undefined);
  });

  test('--force: the same message, prefixed `Overriding:`, then it goes ahead', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.take();
    w.ctx.fetch = answer({ busy: true, counts: { snapshot: 1 } });
    assert.equal(await restart(w.ctx, { force: true }), 0);
    let r = w.take();
    assert.equal(r.err, 'Overriding: Local Review is busy: 1 backup snapshot is running.\n');
    assert.match(r.out, /^Restarted Local Review/m);
    assert.equal(await stop(w.ctx, { force: true }), 0);
    r = w.take();
    assert.equal(r.err, 'Overriding: Local Review is busy: 1 backup snapshot is running.\n');
    assert.match(r.out, /^Stopped Local Review\./);
  });

  test("nothing answering, or an older version without /api/busy: it goes ahead (there's nothing to cut short)", async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.take();
    w.ctx.fetch = async () => new Response('{"error":"not found"}', { status: 404 });
    assert.equal(await restart(w.ctx), 0);
    assert.equal(w.take().err, '');
    w.ctx.fetch = async () => {
      throw new Error('connection refused');
    };
    assert.equal(await stop(w.ctx), 0);
    // a stopped service isn't asked at all
    let asked = 0;
    w.ctx.fetch = async () => (asked++, answer(BUSY)());
    assert.equal(await stop(w.ctx), 0);
    assert.equal(asked, 0);
  });
});

describe('launchd: the bootout → bootstrap race', () => {
  function rig(script: { printsAfterBootout: number; bootstrapCodes: number[] }) {
    const calls: string[] = [];
    let loaded = true;
    let prints = 0;
    const codes = [...script.bootstrapCodes];
    const run: Runner = async (cmd, args) => {
      calls.push(`${cmd} ${args[0]}`);
      const [verb] = args;
      if (verb === 'bootout') {
        prints = script.printsAfterBootout; // launchd is still taking it down for this many `print`s
        return { code: 0, stdout: '', stderr: '' };
      }
      if (verb === 'print') {
        if (prints > 0) return prints--, { code: 0, stdout: '\tstate = running\n', stderr: '' };
        return loaded && prints === 0 && !calls.includes('launchctl bootout') ? { code: 0, stdout: '\tstate = running\n\tpid = 7\n', stderr: '' } : { code: 113, stdout: '', stderr: 'Could not find service' };
      }
      if (verb === 'bootstrap') {
        const code = codes.shift() ?? 0;
        if (code === 0) loaded = true;
        return { code, stdout: '', stderr: code === 5 ? 'Bootstrap failed: 5: Input/output error' : '' };
      }
      return { code: 0, stdout: '', stderr: '' };
    };
    const slept: number[] = [];
    const m = launchdManager({ dir: '/Users/me/Library/LaunchAgents', label: 'local-review.server', uid: 501, run, sleep: async (ms) => void slept.push(ms) });
    return { m, calls, slept };
  }

  test('a reload waits until `print` no longer finds the job before it bootstraps', async () => {
    const r = rig({ printsAfterBootout: 3, bootstrapCodes: [0] });
    await r.m.restart({ reload: true });
    const after = r.calls.slice(r.calls.indexOf('launchctl bootout'));
    assert.deepEqual(after, ['launchctl bootout', 'launchctl print', 'launchctl print', 'launchctl print', 'launchctl print', 'launchctl enable', 'launchctl bootstrap']);
    assert.deepEqual(r.slept, [250, 250, 250]);
  });

  test('error 5 or 37 from the bootstrap is retried, 500 ms apart (cli-contract SPEC §7)', async () => {
    const r = rig({ printsAfterBootout: 0, bootstrapCodes: [5, 37, 0] });
    await r.m.restart({ reload: true });
    assert.equal(r.calls.filter((c) => c === 'launchctl bootstrap').length, 3);
    assert.deepEqual(r.slept, [500, 500]);
  });

  test('error 5 six times, or any other error, fails with what launchctl said', async () => {
    const always = rig({ printsAfterBootout: 0, bootstrapCodes: [5, 5, 5, 5, 5, 5, 0] });
    await assert.rejects(always.m.restart({ reload: true }), /launchctl bootstrap gui\/501 .* failed \(exit 5\): Bootstrap failed: 5: Input\/output error/);
    assert.equal(always.calls.filter((c) => c === 'launchctl bootstrap').length, 6, 'bounded: five retries');
    const other = rig({ printsAfterBootout: 0, bootstrapCodes: [112] });
    await assert.rejects(other.m.restart({ reload: true }), /failed \(exit 112\)/);
    assert.equal(other.calls.filter((c) => c === 'launchctl bootstrap').length, 1, 'not retried');
  });
});

describe('service install --refresh (cli-contract SPEC §1, §5 step 11)', () => {
  test('nothing installed: exit 4, and nothing written or started', async () => {
    const w = world('linux');
    assert.equal(await install(w.ctx, { refresh: true }), 4);
    assert.match(w.take().err, /^local-review: Local Review isn't installed as a service, so there's nothing to refresh/);
    assert.ok(!fs.existsSync(w.file));
    assert.deepEqual(w.calls, []);
  });

  for (const platform of ['linux', 'darwin'] as const)
    test(`${platform}: re-renders from what the service records, not this shell, and restarts it; --port still wins`, async () => {
      const w = world(platform);
      w.ctx.env = { ...w.ctx.env, LOCAL_REVIEW_HOME: path.join(w.userHome, 'kept'), LOCAL_REVIEW_USER: 'Ed' };
      await install(w.ctx, { port: 6001 });
      const before = fs.readFileSync(w.file, 'utf8');
      w.take();
      // a different shell: another data home, no user, another PATH. None of it is what the service was installed with
      w.ctx.env = { PATH: '/usr/bin:/bin', LOCAL_REVIEW_HOME: path.join(w.userHome, 'elsewhere') };
      assert.equal(await install(w.ctx, { refresh: true }), 0);
      const calls = [...w.calls];
      const { out } = w.take();
      assert.equal(fs.readFileSync(w.file, 'utf8'), before, 'byte-identical: the same Node, CLI, port, environment and PATH');
      assert.match(out, /^Refreshed Local Review as a .*\(unchanged\)\nIt's running: http:\/\/localhost:6001\n$/);
      // unchanged, but restarted all the same: update runs this to bring up the version it has just installed
      assert.ok(calls.some((c) => /^systemctl --user restart |^launchctl kickstart -k /.test(c)), calls.join('\n'));
      assert.ok(!fs.existsSync(path.join(w.userHome, 'elsewhere')), "this shell's LOCAL_REVIEW_HOME isn't used");
      // flags given with it still win
      assert.equal(await install(w.ctx, { refresh: true, port: 6002 }), 0);
      const def = (platform === 'darwin' ? parsePlist : parseUnit)(fs.readFileSync(w.file, 'utf8'))!;
      assert.equal(portOf(def.program), 6002);
      assert.equal(def.env.LOCAL_REVIEW_HOME, path.join(w.userHome, 'kept'));
      assert.equal(def.env.LOCAL_REVIEW_USER, 'Ed');
    });

  test('a service installed from a checkout on purpose is refreshed from it without --from-checkout', async () => {
    const co = world('linux', { where: 'checkout' });
    assert.equal(await install(co.ctx, { fromCheckout: true }), 0);
    co.take();
    assert.equal(await install(co.ctx, { refresh: true }), 0);
    // a plain install still refuses it
    await assert.rejects(install(co.ctx, {}), /source checkout/);
  });

  test('a stopped service is started by the refresh', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.state.running = false;
    w.take();
    assert.equal(await install(w.ctx, { refresh: true }), 0);
    assert.equal(w.state.running, true);
  });
});

describe("service status repeats the last update check (cli-contract SPEC §3), and never asks the registry", () => {
  const cache = (home: string, o: { current: string; target: string; updateAvailable: boolean; checkedAt?: string }) => {
    fs.mkdirSync(home, { recursive: true });
    fs.writeFileSync(
      path.join(home, 'update-check.json'),
      JSON.stringify({ name: 'local-review', installMethod: 'npm-global', canUpdate: true, checkedAt: new Date().toISOString(), ...o }),
    );
  };

  test('installed: from the data home the service uses; the notice on stderr, with and without --json', async () => {
    const w = world('linux');
    w.ctx.version = '1.0.0';
    await install(w.ctx, {});
    w.take();
    w.ctx.fetch = async () => {
      throw new Error('connection refused'); // and the registry is never asked: only /api/busy goes through fetch
    };
    cache(path.join(w.userHome, '.local-review'), { current: '1.0.0', target: '1.1.0', updateAvailable: true });
    assert.equal(await status(w.ctx, { json: true }), 0);
    let r = w.take();
    const doc = JSON.parse(r.out);
    assert.equal(doc.update.latest, '1.1.0');
    assert.equal(doc.update.updateAvailable, true);
    assert.match(r.err, /^Local Review 1\.1\.0 is available \(you have 1\.0\.0\)\.\n  Run: local-review update\n  Changes: https:\/\/github\.com\/edspencer\/local-review\/releases\/tag\/v1\.1\.0\n$/);
    assert.equal(await status(w.ctx), 0);
    r = w.take();
    assert.doesNotMatch(r.out, /available/);
    assert.match(r.err, /Local Review 1\.1\.0 is available/);
  });

  test('left out, never null: no cache, a cache for another version, or nothing available', async () => {
    const w = world('linux');
    w.ctx.version = '1.0.0';
    w.ctx.dataHome = path.join(w.userHome, 'here');
    assert.equal(await status(w.ctx, { json: true }), 4);
    assert.ok(!('update' in JSON.parse(w.take().out)));
    // the cache is about 0.9.0, and this is 1.0.0: an update has happened since, so it says nothing
    cache(w.ctx.dataHome, { current: '0.9.0', target: '1.0.0', updateAvailable: true });
    await status(w.ctx, { json: true });
    let r = w.take();
    assert.ok(!('update' in JSON.parse(r.out)));
    assert.equal(r.err, '');
    // nothing installed: it's read from this command's data home; up to date, so no notice
    cache(w.ctx.dataHome, { current: '1.0.0', target: '1.0.0', updateAvailable: false });
    await status(w.ctx, { json: true });
    r = w.take();
    assert.deepEqual(JSON.parse(r.out).update, { latest: '1.0.0', updateAvailable: false, checkedAt: JSON.parse(fs.readFileSync(path.join(w.ctx.dataHome, 'update-check.json'), 'utf8')).checkedAt });
    assert.equal(r.err, '');
  });
});

describe("update's service hooks (server/update.ts → updateHooks)", () => {
  /** A stand-in CLI: records how it was run, and exits with $FAKE_EXIT. */
  const fakeCli = (dir: string) => {
    const f = path.join(dir, 'fake-cli.mjs');
    fs.writeFileSync(f, "import fs from 'node:fs';\nfs.appendFileSync(process.env.FAKE_LOG, JSON.stringify(process.argv.slice(2)) + '\\n');\nprocess.stderr.write('local-review: it said no\\n');\nprocess.exitCode = Number(process.env.FAKE_EXIT ?? 0);\n");
    return f;
  };

  test('installed: the service data home and port; stop is `service stop --force` by this CLI; refresh is `service install --refresh` by the one named', async () => {
    const w = world('linux');
    w.ctx.env = { ...w.ctx.env, LOCAL_REVIEW_HOME: path.join(w.userHome, 'data') };
    await install(w.ctx, { port: 6001 });
    w.take();
    w.ctx.execPath = process.execPath; // the hooks' children are real
    w.ctx.dataHome = path.join(w.userHome, 'not-this-one');
    const cli = fakeCli(TMP);
    const log = path.join(TMP, `hooks-${Date.now()}.log`);
    process.env.FAKE_LOG = log;
    try {
      const h = await updateHooks(w.ctx, { cli });
      assert.equal(h.home, path.join(w.userHome, 'data'), "the service's data home: the one `service status` reads update-check.json from");
      assert.equal(h.busyUrl, 'http://127.0.0.1:6001');
      assert.deepEqual(h.hooks.inspect(), { installed: true, running: true, url: 'http://127.0.0.1:6001', log: path.join(w.userHome, 'data', 'logs', 'service.log') });
      h.hooks.stop();
      const refreshed = h.hooks.refresh(cli);
      assert.equal(refreshed.status, 0);
      assert.deepEqual(fs.readFileSync(log, 'utf8').trim().split('\n').map((l) => JSON.parse(l)), [
        ['service', 'stop', '--force'],
        ['service', 'install', '--refresh'],
      ]);
      process.env.FAKE_EXIT = '1';
      assert.throws(() => h.hooks.stop(), /^Error: it said no$/);
      assert.equal(h.hooks.refresh(cli).status, 1);
      fs.writeFileSync(path.join(w.userHome, 'data', 'logs', 'service.log'), 'one\ntwo\nthree\n');
      assert.equal(h.hooks.tail(2), 'two\nthree\n');
    } finally {
      delete process.env.FAKE_LOG;
      delete process.env.FAKE_EXIT;
    }
  });

  test("not installed: this command's data home, and a foreground `serve` found only through its runtime.json", async () => {
    const w = world('linux');
    w.ctx.dataHome = path.join(w.userHome, 'here');
    const h = await updateHooks(w.ctx, { cli: '/nowhere' });
    assert.equal(h.home, w.ctx.dataHome);
    assert.equal(h.busyUrl, undefined);
    assert.deepEqual(h.hooks.inspect(), { installed: false, running: false });
    fs.mkdirSync(w.ctx.dataHome, { recursive: true });
    fs.writeFileSync(path.join(w.ctx.dataHome, 'runtime.json'), JSON.stringify({ pid: process.pid, port: 7777, url: 'http://127.0.0.1:7777', version: '9.9.9', startedAt: new Date().toISOString() }));
    assert.deepEqual(h.hooks.inspect(), { installed: false, running: true, url: 'http://127.0.0.1:7777' });
    assert.equal(h.hooks.tail(20), '');
  });
});

describe('doctor (cli-contract SPEC §1)', () => {
  const registry = (latest: string) => async (url: string | URL | Request) => {
    const u = String(url);
    if (u.endsWith('/api/health')) throw new Error('connection refused');
    if (u.includes('/dist-tags')) return new Response(JSON.stringify({ latest }));
    return new Response(JSON.stringify({ name: 'local-review', version: latest, engines: { node: '>=22' } }));
  };
  const run = (w: ReturnType<typeof world>, o: Partial<Parameters<typeof diagnose>[0]> = {}) =>
    diagnose({
      ctx: w.ctx,
      version: '1.0.0',
      engines: '>=22',
      home: path.join(w.userHome, '.local-review'),
      entry: w.cli,
      nodeVersion: '22.12.0',
      npmGlobalRoot: () => path.dirname(w.root),
      registry: 'http://registry.test',
      isListening: async () => false,
      linger: async () => true,
      path: w.ctx.env.PATH,
      ...o,
    });

  test('a healthy install: every check passes, in the documented order, and the result is cached for `service status`', async () => {
    const w = world('linux');
    w.ctx.fetch = registry('1.0.0') as typeof fetch;
    fs.writeFileSync(path.join(w.bin, 'gh'), '#!/bin/sh\n', { mode: 0o755 });
    const { checks, notice } = await run(w);
    assert.deepEqual(
      checks.map((c) => `${c.id} ${c.status}`),
      ['node-engines pass', 'install-method pass', 'unit skip', 'running-version skip', 'port pass', 'linger pass', 'data-home pass', 'git pass', 'gh pass', 'update pass'],
    );
    assert.equal(notice, undefined);
    assert.equal(doctorCode(checks), 0);
    const cached = JSON.parse(fs.readFileSync(path.join(w.userHome, '.local-review', 'update-check.json'), 'utf8'));
    assert.equal(cached.current, '1.0.0');
    assert.equal(cached.updateAvailable, false);
    assert.match(renderChecks(checks), /^✓ Node 22\.12\.0 \(Local Review needs >=22\)\n✓ Local Review 1\.0\.0, installed globally with npm: `local-review update` can update it\n- it isn't installed as a service/);
  });

  test('failures have a fix, warnings keep exit 0, --offline never asks the registry', async () => {
    const w = world('linux', { where: 'checkout' });
    w.ctx.fetch = async () => {
      throw new Error('the registry was asked');
    };
    const { checks } = await run(w, { nodeVersion: '20.1.0', isListening: async () => true, offline: true, path: '/nowhere' });
    const by = Object.fromEntries(checks.map((c) => [c.id, c]));
    assert.equal(by['node-engines'].status, 'fail');
    assert.match(by['node-engines'].message, /Node 20\.1\.0 is too old: Local Review 1\.0\.0 needs Node >=22/);
    assert.equal(by['install-method'].status, 'warn');
    assert.match(by['install-method'].fix!, /^git pull && npm install && npm run build/);
    assert.equal(by.port.status, 'fail');
    assert.match(by.port.message, /something that isn't Local Review is listening on port 5622/);
    assert.equal(by.git.status, 'fail');
    assert.equal(by.gh.status, 'warn');
    assert.equal(by.update.status, 'skip');
    for (const c of checks) if (c.status === 'fail') assert.ok(c.fix, `${c.id} has a fix`);
    assert.equal(doctorCode(checks), 1);
    assert.match(renderChecks(checks), /^✗ Node 20\.1\.0 is too old.*\n    fix: install Node >=22/m);
  });

  test('the service: a Node that has gone fails, linger off warns, a newer version warns with the notice', async () => {
    const w = world('linux');
    await install(w.ctx, {});
    w.take();
    fs.rmSync(w.node);
    w.ctx.fetch = registry('1.2.0') as typeof fetch;
    const { checks, notice } = await run(w, { linger: async () => false });
    const by = Object.fromEntries(checks.map((c) => [c.id, c]));
    assert.equal(by.unit.status, 'fail');
    assert.match(by.unit.message, /The Node it runs, .* isn't there any more/);
    assert.equal(by.linger.status, 'warn');
    assert.match(by.linger.fix!, /^sudo loginctl enable-linger /);
    assert.equal(by.update.status, 'warn');
    assert.match(notice!, /^Local Review 1\.2\.0 is available \(you have 1\.0\.0\)\.\n  Run: local-review update\n/);
  });

  test('a registry that does not answer is a warning, not a failure', async () => {
    const w = world('darwin');
    w.ctx.fetch = async () => {
      throw new Error('getaddrinfo ENOTFOUND');
    };
    const { checks } = await run(w);
    const update = checks.find((c) => c.id === 'update')!;
    assert.equal(update.status, 'warn');
    assert.match(update.fix!, /--offline/);
    assert.equal(checks.find((c) => c.id === 'linger')!.status, 'skip');
  });
});
